export default function Word({ word }) {
  const [isShow, setIsShow] = useState(false);
  return (
    <tr>
      <td>
        <input type="checkbox" />
      </td>
      <td>{word.eng}</td>
      <td>{word.kor}</td>
      <td>
        <button>뜻 보기</button>
        <button class="btn_del">삭제</button>
      </td>
    </tr>
  );
}
